) COMMENT='Retail by store and day together with aggregated revenues (previous year s year-to-date ) to check, if PY_SWDAY_BYTD columns are calculated correctly\ninput datasets:\ncore_dim.t_fact_retail_by_store_day\ncore_rel.t_cal_date_adjusted_relationship\ncore_dim.t_dim_calendar_date'
 as SELECT coalesce(fact.bus_dt, agg.cal_dt) AS bus_dt, coalesce(fact.int_org_sid, agg.int_org_sid) AS int_org_sid, fact.int_org_type_cd, fact.country_org_cd, fact.sales_cnt, fact.sales_bytd_cnt, fact.sales_py_cnt, fact.sales_py_bytd_cnt, fact.sales_py_swday_cnt, fact.sales_py_swday_bytd_cnt, agg.calc_sales_py_swday_bytd_cnt, fact.sales_qty, fact.sales_bytd_qty, fact.sales_py_qty, fact.sales_py_bytd_qty, fact.sales_py_swday_qty, fact.sales_py_swday_bytd_qty, agg.calc_sales_py_swday_bytd_qty, fact.return_cnt, fact.return_bytd_cnt, fact.return_py_cnt, fact.return_py_bytd_cnt, fact.return_py_swday_cnt, fact.return_py_swday_bytd_cnt, agg.calc_return_py_swday_bytd_cnt, fact.return_qty, fact.return_bytd_qty, fact.return_py_qty, fact.return_py_bytd_qty, fact.return_py_swday_qty, fact.return_py_swday_bytd_qty, agg.calc_return_py_swday_bytd_qty, fact.perf_adj_sales_cnt, fact.perf_adj_sales_bytd_cnt, fact.perf_adj_sales_py_cnt, fact.perf_adj_sales_py_bytd_cnt, fact.perf_adj_sales_py_swday_cnt, fact.perf_adj_sales_py_swday_bytd_cnt, agg.calc_perf_adj_sales_py_swday_bytd_cnt, fact.perf_adj_sales_qty, fact.perf_adj_sales_bytd_qty, fact.perf_adj_sales_py_qty, fact.perf_adj_sales_py_bytd_qty, fact.perf_adj_sales_py_swday_qty, fact.perf_adj_sales_py_swday_bytd_qty, agg.calc_perf_adj_sales_py_swday_bytd_qty, fact.perf_adj_return_cnt, fact.perf_adj_return_bytd_cnt, fact.perf_adj_return_py_cnt, fact.perf_adj_return_py_bytd_cnt, fact.perf_adj_return_py_swday_cnt, fact.perf_adj_return_py_swday_bytd_cnt, agg.calc_perf_adj_return_py_swday_bytd_cnt, fact.perf_adj_return_qty, fact.perf_adj_return_bytd_qty, fact.perf_adj_return_py_qty, fact.perf_adj_return_py_bytd_qty, fact.perf_adj_return_py_swday_qty, fact.perf_adj_return_py_swday_bytd_qty, agg.calc_perf_adj_return_py_swday_bytd_qty, fact.uom_cd, fact.turnover_net_val, fact.turnover_bytd_net_val, fact.turnover_py_net_val, fact.turnover_py_bytd_net_val, fact.turnover_py_swday_net_val, fact.turnover_py_swday_bytd_net_val, agg.calc_turnover_py_swday_bytd_net_val, fact.plan_turnover_net_val, fact.plan_turnover_bytd_net_val, fact.plan_turnover_py_net_val, fact.plan_turnover_py_bytd_net_val, fact.plan_turnover_py_swday_net_val, fact.plan_turnover_py_swday_bytd_net_val, agg.calc_plan_turnover_py_swday_bytd_net_val, fact.cash_register_sales_net_val, fact.cash_register_sales_bytd_net_val, fact.cash_register_sales_py_net_val, fact.cash_register_sales_py_bytd_net_val, fact.cash_register_sales_py_swday_net_val, fact.cash_register_sales_py_swday_bytd_net_val, agg.calc_cash_register_sales_py_swday_bytd_net_val, fact.cash_register_return_net_val, fact.cash_register_return_bytd_net_val, fact.cash_register_return_py_net_val, fact.cash_register_return_py_bytd_net_val, fact.cash_register_return_py_swday_net_val, fact.cash_register_return_py_swday_bytd_net_val, agg.calc_cash_register_return_py_swday_bytd_net_val, fact.eod_turnover_net_val, fact.booked_turnover_net_val, fact.turnover_gross_val, fact.turnover_bytd_gross_val, fact.turnover_py_gross_val, fact.turnover_py_bytd_gross_val, fact.turnover_py_swday_gross_val, fact.turnover_py_swday_bytd_gross_val, agg.calc_turnover_py_swday_bytd_gross_val, fact.cash_register_sales_gross_val, fact.cash_register_return_gross_val, fact.eod_turnover_gross_val, fact.curr_cd, fact.receipt_cnt, fact.receipt_bytd_cnt, fact.receipt_py_cnt, fact.receipt_py_bytd_cnt, fact.receipt_py_swday_cnt, fact.receipt_py_swday_bytd_cnt, agg.calc_receipt_py_swday_bytd_cnt, fact.cash_register_receipt_cnt, fact.eod_receipt_cnt, fact.booked_receipt_cnt, fact.plan_receipt_cnt, fact.plan_receipt_bytd_cnt, fact.plan_receipt_py_cnt, fact.plan_receipt_py_bytd_cnt, fact.plan_receipt_py_swday_cnt, fact.plan_receipt_py_swday_bytd_cnt, agg.calc_plan_receipt_py_swday_bytd_cnt, fact.dwh_created_tmsp, fact.dwh_updated_tmsp, fact.dwh_load_id, fact.dwh_node_cd, CASE WHEN ( COALESCE(fact.turnover_py_swday_bytd_net_val, -1) != COALESCE(agg.calc_turnover_py_swday_bytd_net_val, -1) ) THEN 1 ELSE 0 END AS failed_turnover_py_swday_bytd_net_val, CASE WHEN ( COALESCE(fact.plan_turnover_py_swday_bytd_net_val, -1) != COALESCE(agg.calc_plan_turnover_py_swday_bytd_net_val, -1) ) THEN 1 ELSE 0 END AS failed_plan_turnover_py_swday_bytd_net_val, CASE WHEN ( COALESCE(fact.turnover_py_swday_bytd_gross_val, -1) != COALESCE(agg.calc_turnover_py_swday_bytd_gross_val, -1) ) THEN 1 ELSE 0 END AS failed_turnover_py_swday_bytd_gross_val, CASE WHEN ( COALESCE(fact.receipt_py_swday_bytd_cnt, -1) != COALESCE(agg.calc_receipt_py_swday_bytd_cnt, -1) ) THEN 1 ELSE 0 END AS failed_receipt_py_swday_bytd_cnt, CASE WHEN ( COALESCE(fact.plan_receipt_py_swday_bytd_cnt, -1) != COALESCE(agg.calc_plan_receipt_py_swday_bytd_cnt, -1) ) THEN 1 ELSE 0 END AS failed_plan_receipt_py_swday_bytd_cnt, CASE WHEN ( COALESCE(fact.sales_py_swday_bytd_cnt, -1) != COALESCE(agg.calc_sales_py_swday_bytd_cnt, -1) ) THEN 1 ELSE 0 END AS failed_sales_py_swday_bytd_cnt, CASE WHEN ( COALESCE(fact.sales_py_swday_bytd_qty, -1) != COALESCE(agg.calc_sales_py_swday_bytd_qty, -1) ) THEN 1 ELSE 0 END AS failed_sales_py_swday_bytd_qty, CASE WHEN ( COALESCE(fact.return_py_swday_bytd_cnt, -1) != COALESCE(agg.calc_return_py_swday_bytd_cnt, -1) ) THEN 1 ELSE 0 END AS failed_return_py_swday_bytd_cnt, CASE WHEN ( COALESCE(fact.return_py_swday_bytd_qty, -1) != COALESCE(agg.calc_return_py_swday_bytd_qty, -1) ) THEN 1 ELSE 0 END AS failed_return_py_swday_bytd_qty, CASE WHEN ( COALESCE(fact.perf_adj_sales_py_swday_bytd_cnt, -1) != COALESCE(agg.calc_perf_adj_sales_py_swday_bytd_cnt, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_sales_py_swday_bytd_cnt, CASE WHEN ( COALESCE(fact.perf_adj_sales_py_swday_bytd_qty, -1) != COALESCE(agg.calc_perf_adj_sales_py_swday_bytd_qty, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_sales_py_swday_bytd_qty, CASE WHEN ( COALESCE(fact.perf_adj_return_py_swday_bytd_cnt, -1) != COALESCE(agg.calc_perf_adj_return_py_swday_bytd_cnt, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_return_py_swday_bytd_cnt, CASE WHEN ( COALESCE(fact.perf_adj_return_py_swday_bytd_qty, -1) != COALESCE(agg.calc_perf_adj_return_py_swday_bytd_qty, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_return_py_swday_bytd_qty, CASE WHEN ( COALESCE(fact.cash_register_sales_py_swday_bytd_net_val, -1) != COALESCE(agg.calc_cash_register_sales_py_swday_bytd_net_val, -1) ) THEN 1 ELSE 0 END AS failed_cash_register_sales_py_swday_bytd_net_val, CASE WHEN ( COALESCE(fact.cash_register_return_py_swday_bytd_net_val, -1) != COALESCE(agg.calc_cash_register_return_py_swday_bytd_net_val, -1) ) THEN 1 ELSE 0 END AS failed_cash_register_return_py_swday_bytd_net_val, 1 AS TOTAL FROM ( SELECT * FROM core_dim.t_fact_retail_by_store_day where bus_dt < current_date ) AS fact FULL OUTER JOIN ( SELECT agg_py.int_org_sid, agg_py.cal_dt, SUM (agg_py.calc_turnover_py_swday_net_val) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_turnover_py_swday_bytd_net_val, SUM (agg_py.calc_plan_turnover_py_swday_net_val) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_plan_turnover_py_swday_bytd_net_val, SUM (agg_py.calc_turnover_py_swday_gross_val) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_turnover_py_swday_bytd_gross_val, SUM (agg_py.calc_receipt_py_swday_cnt) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_receipt_py_swday_bytd_cnt, SUM (agg_py.calc_plan_receipt_py_swday_cnt) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_plan_receipt_py_swday_bytd_cnt, SUM (agg_py.calc_sales_py_swday_bytd_cnt) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_sales_py_swday_bytd_cnt, SUM (agg_py.calc_sales_py_swday_bytd_qty) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_sales_py_swday_bytd_qty, SUM (agg_py.calc_return_py_swday_bytd_cnt) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_return_py_swday_bytd_cnt, SUM (agg_py.calc_return_py_swday_bytd_qty) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_return_py_swday_bytd_qty, SUM (agg_py.calc_perf_adj_sales_py_swday_bytd_cnt) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_perf_adj_sales_py_swday_bytd_cnt, SUM (agg_py.calc_perf_adj_sales_py_swday_bytd_qty) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_perf_adj_sales_py_swday_bytd_qty, SUM (agg_py.calc_perf_adj_return_py_swday_bytd_cnt) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_perf_adj_return_py_swday_bytd_cnt, SUM (agg_py.calc_perf_adj_return_py_swday_bytd_qty) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_perf_adj_return_py_swday_bytd_qty, SUM (agg_py.calc_cash_register_sales_py_swday_bytd_net_val) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_cash_register_sales_py_swday_bytd_net_val, SUM (agg_py.calc_cash_register_return_py_swday_bytd_net_val) OVER ( PARTITION BY agg_py.int_org_sid, agg_py.bus_year ORDER BY agg_py.cal_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calc_cash_register_return_py_swday_bytd_net_val FROM ( SELECT base.int_org_sid AS int_org_sid, c.cal_dt AS cal_dt, MAX(c.bus_year) AS bus_year, SUM (prev_year_fact.turnover_net_val) AS calc_turnover_py_swday_net_val, SUM (prev_year_fact.plan_turnover_net_val) AS calc_plan_turnover_py_swday_net_val, SUM (prev_year_fact.turnover_gross_val) AS calc_turnover_py_swday_gross_val, SUM (prev_year_fact.receipt_cnt) AS calc_receipt_py_swday_cnt, SUM (prev_year_fact.plan_receipt_cnt) AS calc_plan_receipt_py_swday_cnt, SUM (prev_year_fact.sales_cnt) AS calc_sales_py_swday_bytd_cnt, SUM (prev_year_fact.sales_qty) AS calc_sales_py_swday_bytd_qty, SUM (prev_year_fact.return_cnt) as calc_return_py_swday_bytd_cnt, SUM (prev_year_fact.return_qty) as calc_return_py_swday_bytd_qty, SUM (prev_year_fact.perf_adj_sales_cnt) as calc_perf_adj_sales_py_swday_bytd_cnt, SUM (prev_year_fact.perf_adj_sales_qty) as calc_perf_adj_sales_py_swday_bytd_qty, SUM (prev_year_fact.perf_adj_return_cnt) as calc_perf_adj_return_py_swday_bytd_cnt, SUM (prev_year_fact.perf_adj_return_qty) as calc_perf_adj_return_py_swday_bytd_qty, SUM (prev_year_fact.cash_register_sales_net_val) as calc_cash_register_sales_py_swday_bytd_net_val, SUM (prev_year_fact.cash_register_return_net_val) as calc_cash_register_return_py_swday_bytd_net_val FROM ( SELECT int_org_sid, Min(bus_dt) min_bus_dt, Max(bus_dt) max_bus_dt FROM core_dim.t_fact_retail_by_store_day WHERE bus_dt < Current_Date GROUP BY 1 ) base INNER JOIN CORE_DIM.t_dim_calendar_date AS c ON c.cal_dt BETWEEN base.min_bus_dt AND base.max_bus_dt LEFT OUTER JOIN CORE_REL.t_cal_date_adjusted_relationship AS dr ON c.cal_dt = dr.cal_dt AND dr.cal_dt_adjust_type_cd = 'WC' AND dr.bus_year_diff = 1 LEFT OUTER JOIN core_dim.t_fact_retail_by_store_day AS prev_year_fact ON prev_year_fact.bus_dt = dr.rel_cal_dt AND prev_year_fact.int_org_sid = base.int_org_sid GROUP BY base.int_org_sid, c.cal_dt ORDER BY base.int_org_sid, c.cal_dt ) agg_py ) AS agg ON fact.int_org_sid = agg.int_org_sid AND fact.bus_dt = agg.cal_dt ORDER BY fact.int_org_sid, fact.bus_dt ASC;